// Extract contact + attribution data from GHL webhook payload.
// GHL's webhook shape varies by trigger type, so we check many possible keys.
const body = $input.first().json.body || $input.first().json;

const rawPhone =
  body?.phone ||
  body?.contact?.phone ||
  body?.contactPhone ||
  body?.data?.phone ||
  body?.customData?.phone ||
  '';

let phone = String(rawPhone).replace(/\D/g, '');
if (phone.startsWith('0')) phone = '44' + phone.slice(1);
if (!phone.startsWith('44') && phone.length === 10) phone = '44' + phone;

const email = (body?.email || body?.contact?.email || body?.data?.email || '').toLowerCase().trim();
const firstName = (body?.firstName || body?.first_name || body?.contact?.firstName || '').toLowerCase().trim();
const lastName = (body?.lastName || body?.last_name || body?.contact?.lastName || '').toLowerCase().trim();

function pickAttribution(key) {
  const candidates = [
    body?.[key],
    body?.contact?.[key],
    body?.attributionSource?.[key],
    body?.lastAttributionSource?.[key],
    body?.firstAttributionSource?.[key],
    body?.customData?.[key],
    body?.customFields?.[key],
    body?.contact?.customFields?.[key]
  ];
  for (const v of candidates) if (v) return v;
  return null;
}

let ctwaClid = pickAttribution('ctwa_clid') || pickAttribution('ctwaClid') || pickAttribution('ctwa');
let adId = pickAttribution('ad_id') || pickAttribution('adId');
let adHeadline = pickAttribution('ad_name') || pickAttribution('adName') || pickAttribution('headline');
let campaignId = pickAttribution('campaign_id') || pickAttribution('campaignId');
let campaignName = pickAttribution('campaign_name') || pickAttribution('campaignName');
let sourceUrl = pickAttribution('source_url') || pickAttribution('sourceUrl');

// Fallback: scrape the message body for prepended Headline / Source URL
const lastMessage = body?.lastMessage?.body || body?.message?.body || body?.body || '';
if (typeof lastMessage === 'string') {
  if (!adHeadline) {
    const m = lastMessage.match(/Headline:\s*(.+?)(?:\n|$)/i);
    if (m) adHeadline = m[1].trim();
  }
  if (!sourceUrl) {
    const m = lastMessage.match(/Source URL:\s*(\S+)/i);
    if (m) sourceUrl = m[1].trim();
  }
}

const contactId = body?.contact_id || body?.contactId || body?.id || body?.contact?.id || '';
const eventTime = Math.floor(Date.now() / 1000);
// Stable event_id for dedup: contact + ctwa_clid if available, else contact + day bucket
const idSeed = ctwaClid ? `${contactId}_${ctwaClid}` : `${contactId}_${Math.floor(eventTime / 86400)}`;
const eventId = `lead_${idSeed}`;

return [{
  json: {
    phone, email, firstName, lastName, contactId,
    ctwaClid, adId, adHeadline, campaignId, campaignName, sourceUrl,
    eventTime, eventId,
    rawPayload: body
  }
}];

const crypto = require('crypto');
const data = $input.first().json;

// Guard: Meta's business_messaging channel requires a real ctwa_clid.
// If the inbound message wasn't a CTWA click, skip the CAPI call entirely.
if (!data.ctwaClid) { return []; }
const sha256 = v => v ? crypto.createHash('sha256').update(String(v)).digest('hex') : null;

const userData = {};
if (data.phone) userData.ph = [sha256(data.phone)];
if (data.email) userData.em = [sha256(data.email)];
if (data.firstName) userData.fn = [sha256(data.firstName)];
if (data.lastName) userData.ln = [sha256(data.lastName)];
if (data.contactId) userData.external_id = [sha256(data.contactId)];
// ctwa_clid is NOT hashed per Meta CAPI spec
if (data.ctwaClid) userData.ctwa_clid = data.ctwaClid;
userData.page_id = '178728745664355';

const customData = {
  content_category: 'WhatsApp Enquiry'
};
if (data.adId) customData.ad_id = data.adId;
if (data.adHeadline) customData.ad_headline = data.adHeadline;
if (data.campaignId) customData.campaign_id = data.campaignId;
if (data.campaignName) customData.campaign_name = data.campaignName;

const payload = {
  data: [{
    event_name: 'LeadSubmitted',
    event_time: data.eventTime,
    event_id: data.eventId,
    action_source: 'business_messaging',
    messaging_channel: 'whatsapp',
    user_data: userData,
    custom_data: customData
  }],
  access_token: 'REPLACE_WITH_META_ACCESS_TOKEN'
};

return [{ json: { payload, debug: { contactId: data.contactId, eventId: data.eventId, hasCtwa: !!data.ctwaClid } } }];

const response = $input.first().json;
const status = response.statusCode || 200;
const body = response.body || response;
const success = status === 200 && body?.events_received > 0;
return [{ json: { success, events_received: body?.events_received || 0, status, fbtrace_id: body?.fbtrace_id, response: body } }];
